import { useEffect, useMemo, useRef, useState } from "react";
import L from "leaflet";
import { CircleMarker, GeoJSON, MapContainer, Popup, TileLayer, Tooltip, useMap } from "react-leaflet";
import "leaflet/dist/leaflet.css";
import {
  ArrowClockwise, ArrowRight, Briefcase, Buildings, ChartBar, ChartDonut, CheckCircle, ClipboardText, Crosshair,
  CurrencyDollar, Database, DownloadSimple, Eye, EyeSlash, Factory, FileText,
  FolderOpen, Funnel, Gear, Info, ListChecks, LockKey, MagnifyingGlass,
  MapPin, MapTrifold, PencilSimple, Plus, Printer, ShieldCheck, SquaresFour, Stack, Trash, TrendUp, UploadSimple,
  UsersThree, Warning, X,
} from "@phosphor-icons/react";
import { Bar, BarChart, CartesianGrid, Cell, Pie, PieChart, ResponsiveContainer, Tooltip as ChartTooltip, XAxis, YAxis } from "recharts";
import { demoDocuments, demoProjects, evaluationCriteria, historicalParks, initialEvaluations, paraguayDepartments, parkCharacters } from "./data.js";
import { auditParkData, downloadText, formatCurrency, formatNumber, loadLocal, parseCsv, parseGeoJson, parseXlsxArrayBuffer, safeId, saveLocal, summarizeEvaluations, toCsv, validateParkImportRows } from "./lib.js";

const navItems = [
  ["dashboard", "Dashboard", SquaresFour, true], ["parques", "Parques", Factory, true],
  ["proyectos", "Proyectos", Briefcase, false], ["gis", "Mapa GIS", MapTrifold, true],
  ["calidad", "Calidad de datos", ShieldCheck, true],
  ["documentos", "Documentos", FolderOpen, false], ["evaluacion", "Evaluación", ClipboardText, false],
  ["reportes", "Reportes", ChartBar, true], ["admin", "Administración", Gear, false],
];
const sourceCut = "Julio de 2025";

function DataState({ type = "official", children }) { return <span className={`data-state ${type}`}>{children}</span>; }
function PageHeading({ eyebrow, title, actions }) { return <div className="page-heading"><div><span>{eyebrow}</span><h1>{title}</h1></div>{actions}</div>; }
function EmptyState({ icon: Icon = Info, title, text }) { return <div className="empty-state"><Icon size={34} weight="duotone" /><strong>{title}</strong><span>{text}</span></div>; }

function Modal({ title, children, onClose }) {
  useEffect(() => { const close = (event) => event.key === "Escape" && onClose(); window.addEventListener("keydown", close); return () => window.removeEventListener("keydown", close); }, [onClose]);
  return <div className="modal-backdrop" role="presentation" onMouseDown={(event) => event.target === event.currentTarget && onClose()}><section className="modal" role="dialog" aria-modal="true" aria-labelledby="modal-title"><header><h2 id="modal-title">{title}</h2><button className="icon-button" onClick={onClose} aria-label="Cerrar"><X size={20} /></button></header>{children}</section></div>;
}

function Sidebar({ active, setActive, publicMode }) {
  return <aside className="sidebar"><div className="brand"><MapTrifold size={30} weight="duotone" /><div><strong>SIGPI</strong><span>Paraguay</span></div></div><nav aria-label="Navegación principal">{navItems.filter(([, , , isPublic]) => !publicMode || isPublic).map(([id, label, Icon]) => <button key={id} className={active === id ? "active" : ""} onClick={() => setActive(id)} title={label}><Icon size={22} weight={active === id ? "fill" : "regular"} /><span>{label}</span></button>)}</nav><div className="sidebar-footer"><DataState type={publicMode ? "calculated" : "pending"}>{publicMode ? "Público" : "Interno"}</DataState><span>Base {sourceCut}</span><small>v0.5</small></div></aside>;
}

function Header({ search, setSearch, publicMode, setPublicMode }) {
  return <header className="topbar"><div className="topbar-title"><strong>SIGPI Paraguay · Centro de Comando Industrial</strong><span>Inteligencia territorial para la inversión industrial</span></div><label className="search-control"><MagnifyingGlass size={18} weight="bold" /><input value={search} onChange={(event) => setSearch(event.target.value)} placeholder="Buscar parques, proyectos o distritos…" aria-label="Buscar" />{search && <button className="icon-button" onClick={() => setSearch("")} aria-label="Limpiar búsqueda"><X size={16} /></button>}</label><div className="source-date"><span>Actualización de interfaz</span><strong>2 nov 2026</strong></div><button className="mode-switch" onClick={() => setPublicMode((value) => !value)} title="Alternar vista pública y gestión local demostrativa">{publicMode ? <Eye size={18} /> : <EyeSlash size={18} />}<span>{publicMode ? "Público" : "Interno demo"}</span></button></header>;
}

function SourceBand({ message }) { return <section className="source-band"><div><Info size={18} weight="fill" /> Modo demostración con base histórica recuperada</div><span>{message}</span><div className="state-legend"><DataState type="official">Histórico</DataState><DataState type="calculated">Calculado</DataState><DataState type="pending">Pendiente</DataState></div></section>; }
function Kpi({ Icon, value, label, note, state = "calculated" }) { return <article className="stat-card"><div className="stat-icon"><Icon size={24} weight="duotone" /></div><div><strong>{value}</strong><span>{label}</span><small>{note}</small></div><DataState type={state}>{state === "official" ? "Histórico" : "Demo"}</DataState></article>; }

const chartColors = ["#27dce3", "#28d17c", "#f4bd3d", "#7399b7", "#b488ff"];

function ParaguayViewport() {
  const map = useMap();
  useEffect(() => { map.fitBounds([[-27.65, -62.68], [-19.28, -54.16]], { padding: [18, 18] }); }, [map]);
  return null;
}

function CommandMap({ parks, selected, setSelected, showMarkers = true }) {
  const mappedParks = parks.filter(validCoordinates);
  return <div className="command-map" aria-label="Centro de comando geográfico de parques industriales">
    <MapContainer center={[-23.45, -58.35]} zoom={5} minZoom={4} maxZoom={18} scrollWheelZoom className="command-leaflet">
      <TileLayer attribution="Tiles &copy; Esri — Source: Esri, Maxar, Earthstar Geographics" maxZoom={19} url="https://server.arcgisonline.com/ArcGIS/rest/services/World_Imagery/MapServer/tile/{z}/{y}/{x}" />
      <TileLayer attribution="Reference &copy; Esri" maxZoom={19} url="https://server.arcgisonline.com/ArcGIS/rest/services/Reference/World_Boundaries_and_Places/MapServer/tile/{z}/{y}/{x}" />
      <ParaguayViewport />
      {showMarkers && mappedParks.map((park) => {
        const active = selected?.id === park.id;
        const point = [Number(park.coordinates.lat), Number(park.coordinates.lon)];
        return <CircleMarker key={park.id} center={point} radius={active ? 12 : 8} pathOptions={{ color: active ? "#ffffff" : "#8df9ff", weight: active ? 4 : 2, fillColor: active ? "#26dce4" : markerColor(park), fillOpacity: 1 }} eventHandlers={{ click: () => setSelected(park) }}>
          <Tooltip direction="top" offset={[0, -9]}>{park.short}</Tooltip>
        </CircleMarker>;
      })}
    </MapContainer>
    <div className="map-command-badge"><Crosshair size={16} weight="bold" /> WGS84 · coordenadas documentales verificadas</div>
  </div>;
}

function Dashboard({ parks, projects, setActive, selected, setSelected }) {
  const [department, setDepartment] = useState("Todos");
  const [character, setCharacter] = useState("Todos");
  const [showMarkers, setShowMarkers] = useState(true);
  const [viewMode, setViewMode] = useState("mapa");
  const [rightMode, setRightMode] = useState("oportunidades");

  const filtered = useMemo(() => parks.filter((park) => (department === "Todos" || park.department === department) && (character === "Todos" || park.character === character)), [parks, department, character]);
  const activePark = filtered.find((park) => park.id === selected?.id) || filtered[0] || parks[0];
  const surface = parks.reduce((sum, park) => sum + Number(park.surface || 0), 0);
  const departments = new Set(parks.map((park) => park.department)).size;
  const byDepartment = Object.entries(parks.reduce((acc, park) => ({ ...acc, [park.department]: (acc[park.department] || 0) + 1 }), {})).map(([name, count]) => ({ name, count })).sort((a, b) => b.count - a.count);
  const surfaceByDepartment = Object.values(parks.reduce((acc, park) => { const current = acc[park.department] || { name: park.department, surface: 0 }; current.surface += Number(park.surface || 0); acc[park.department] = current; return acc; }, {})).sort((a, b) => b.surface - a.surface);
  const byCharacter = Object.entries(parks.reduce((acc, park) => ({ ...acc, [park.character]: (acc[park.character] || 0) + 1 }), {})).map(([name, value]) => ({ name, value }));
  const largestPark = [...parks].sort((a, b) => Number(b.surface) - Number(a.surface))[0];
  const exportDashboard = () => downloadText("sigpi-parques.csv", toCsv(parks, [["Parque", "name"], ["Departamento", "department"], ["Distrito", "city"], ["Carácter", "character"], ["Superficie (ha)", "surface"], ["Resolución", "resolution"]]), "text/csv;charset=utf-8");
  const openPark = (park) => { setSelected(park); setActive("gis"); };

  return <section className="command-dashboard">
    <div className="command-toolbar">
      <div><span>Explorar territorio</span><strong>Parques industriales del Paraguay</strong></div>
      <div className="toolbar-actions">
        <button className="command-secondary" onClick={exportDashboard}><DownloadSimple size={17} /> Exportar reporte</button>
        <button className="command-primary" onClick={() => setActive("gis")}><Crosshair size={17} /> Analizar territorio</button>
      </div>
    </div>

    <div className="command-kpis">
      <article><Factory size={24} weight="duotone" /><strong>{parks.length}</strong><span>parques en la base</span><DataState type="official">Base documental</DataState></article>
      <article><MapTrifold size={24} weight="duotone" /><strong>{formatNumber(surface, { maximumFractionDigits: 2 })} ha</strong><span>superficie registrada</span><DataState type="calculated">Calculado</DataState></article>
      <article><MapPin size={24} weight="duotone" /><strong>{departments}</strong><span>departamentos</span><DataState type="official">Base documental</DataState></article>
      <article><Briefcase size={24} weight="duotone" /><strong>{projects.length}</strong><span>proyectos en seguimiento</span><DataState type="pending">Demostrativo</DataState></article>
    </div>

    <div className="command-stage">
      <aside className="territory-controls">
        <div className="dock-title"><Funnel size={17} /> Filtros territoriales</div>
        <label>Departamento<select value={department} onChange={(event) => setDepartment(event.target.value)}>{paraguayDepartments.map((item) => <option key={item}>{item}</option>)}</select></label>
        <label>Distrito<select defaultValue="Todos"><option>Todos</option>{[...new Set(filtered.map((park) => park.city))].map((city) => <option key={city}>{city}</option>)}</select></label>
        <label>Estado<select defaultValue="Habilitado"><option>Todos</option><option>Habilitado</option><option>En análisis</option></select></label>
        <label>Tipo de parque<select value={character} onChange={(event) => setCharacter(event.target.value)}>{parkCharacters.map((item) => <option key={item}>{item}</option>)}</select></label>
        <button className="command-primary wide" onClick={() => setActive("gis")}><TrendUp size={17} /> Analizar selección <ArrowRight size={15} /></button>
        <div className="layer-controls">
          <div className="dock-title"><Stack size={17} /> Capas del mapa</div>
          <label className="layer-toggle"><input type="checkbox" checked={showMarkers} onChange={(event) => setShowMarkers(event.target.checked)} /><span>Parques industriales</span></label>
          <label className="layer-toggle"><input type="checkbox" disabled /><span>Corredores logísticos</span><small>Pendiente</small></label>
          <label className="layer-toggle"><input type="checkbox" disabled /><span>Polígonos catastrales</span><small>Pendiente</small></label>
        </div>
        <p className="dock-note">Los puntos corresponden a coordenadas WGS84 recuperadas de fichas DGFI. No representan polígonos prediales.</p>
      </aside>

      <div className="map-workspace">
        <div className="map-top-controls"><div><button className={viewMode === "mapa" ? "active" : ""} onClick={() => setViewMode("mapa")}>Mapa</button><button className={viewMode === "lista" ? "active" : ""} onClick={() => setViewMode("lista")}>Lista</button></div><span>{filtered.length} ubicaciones</span></div>
        {viewMode === "mapa" ? <CommandMap parks={filtered} selected={activePark} setSelected={setSelected} showMarkers={showMarkers} /> : <div className="map-list-view">{filtered.map((park) => <button key={park.id} onClick={() => setSelected(park)} className={activePark?.id === park.id ? "active" : ""}><MapPin size={18} /><span><strong>{park.short}</strong><small>{park.city} · {park.department}</small></span><b>{formatNumber(park.surface)} ha</b></button>)}</div>}
        {activePark && <div className="selected-map-card"><div className="selected-pulse"><MapPin size={20} weight="fill" /></div><div><span>Selección activa</span><strong>{activePark.short}</strong><small>{activePark.city} · {activePark.department} · {formatNumber(activePark.surface)} ha</small></div><button onClick={() => openPark(activePark)} aria-label="Abrir ficha"><ArrowRight size={19} /></button></div>}
      </div>

      <aside className="insight-dock">
        <div className="insight-tabs"><button className={rightMode === "oportunidades" ? "active" : ""} onClick={() => setRightMode("oportunidades")}>Oportunidades</button><button className={rightMode === "radar" ? "active" : ""} onClick={() => setRightMode("radar")}>Radar de parques</button></div>
        {rightMode === "oportunidades" ? <div className="opportunities-panel">
          <div className="opportunity-visual"><img src="./assets/oportunidad-industrial-paraguay.webp" alt="Visual demostrativo de un parque industrial moderno" /><div><DataState type="calculated">Lectura calculada</DataState><strong>Oportunidades territoriales</strong><span>Señales de la base; no constituyen evaluación de factibilidad.</span></div></div>
          <button className="opportunity-row" onClick={() => setDepartment(byDepartment[0]?.name || "Todos")}><span><ChartBar size={19} /><b>Mayor concentración</b><small>{byDepartment[0]?.name}: {byDepartment[0]?.count} parques registrados</small></span><ArrowRight size={17} /></button>
          <button className="opportunity-row" onClick={() => openPark(largestPark)}><span><Factory size={19} /><b>Mayor superficie registrada</b><small>{largestPark?.short}: {formatNumber(largestPark?.surface)} ha</small></span><ArrowRight size={17} /></button>
          <button className="opportunity-row" onClick={() => setDepartment("Central")}><span><MapPin size={19} /><b>Nodo metropolitano</b><small>Central: {parks.filter((park) => park.department === "Central").length} parques documentados</small></span><ArrowRight size={17} /></button>
        </div> : <div className="radar-list">{parks.slice(0, 6).map((park) => <button key={park.id} className={activePark?.id === park.id ? "active" : ""} onClick={() => setSelected(park)}><span><strong>{park.short}</strong><small>{park.city} · {park.department}</small></span><b>{formatNumber(park.surface)} ha</b></button>)}</div>}
        {activePark && <div className="park-intel"><div className="park-intel-head"><div><span>Parque seleccionado</span><strong>{activePark.short}</strong></div><DataState type={activePark.sourceState?.includes("Histórico") ? "official" : "pending"}>{activePark.status}</DataState></div><dl><div><dt>Departamento</dt><dd>{activePark.department}</dd></div><div><dt>Distrito</dt><dd>{activePark.city}</dd></div><div><dt>Superficie</dt><dd>{formatNumber(activePark.surface)} ha</dd></div><div><dt>Carácter</dt><dd>{activePark.character}</dd></div></dl><button className="command-primary wide" onClick={() => openPark(activePark)}>Abrir ficha <ArrowRight size={16} /></button></div>}
      </aside>
    </div>

    <div className="analytics-console">
      <section><header><div><ChartBar size={18} /><span>Distribución territorial</span></div><small>Base documental</small></header><ResponsiveContainer width="100%" height={155}><BarChart data={byDepartment} layout="vertical" margin={{ top: 5, right: 12, bottom: 0, left: 4 }}><XAxis type="number" hide /><YAxis type="category" dataKey="name" width={92} tick={{ fill: "#a9bec5", fontSize: 10 }} axisLine={false} tickLine={false} /><ChartTooltip contentStyle={{ background: "#071d2a", border: "1px solid #19485d", color: "#fff" }} /><Bar dataKey="count" fill="#28dce3" radius={[0, 4, 4, 0]} barSize={11} /></BarChart></ResponsiveContainer></section>
      <section><header><div><ChartDonut size={18} /><span>Tipología de parque</span></div><small>Base documental</small></header><div className="donut-wrap"><ResponsiveContainer width="58%" height={155}><PieChart><Pie data={byCharacter} dataKey="value" nameKey="name" innerRadius={42} outerRadius={63} paddingAngle={3}>{byCharacter.map((entry, index) => <Cell key={entry.name} fill={chartColors[index % chartColors.length]} />)}</Pie><ChartTooltip contentStyle={{ background: "#071d2a", border: "1px solid #19485d", color: "#fff" }} /></PieChart></ResponsiveContainer><div className="chart-legend">{byCharacter.map((entry, index) => <span key={entry.name}><i style={{ background: chartColors[index % chartColors.length] }} />{entry.name}<b>{entry.value}</b></span>)}</div></div></section>
      <section><header><div><TrendUp size={18} /><span>Superficie registrada</span></div><small>Calculado</small></header><ResponsiveContainer width="100%" height={155}><BarChart data={surfaceByDepartment} margin={{ top: 8, right: 6, bottom: 0, left: -20 }}><CartesianGrid stroke="#12374a" vertical={false} /><XAxis dataKey="name" tick={{ fill: "#829ca8", fontSize: 9 }} axisLine={false} tickLine={false} /><YAxis tick={{ fill: "#829ca8", fontSize: 9 }} axisLine={false} tickLine={false} /><ChartTooltip formatter={(value) => [`${formatNumber(value)} ha`, "Superficie"]} contentStyle={{ background: "#071d2a", border: "1px solid #19485d", color: "#fff" }} /><Bar dataKey="surface" radius={[4, 4, 0, 0]}>{surfaceByDepartment.map((entry, index) => <Cell key={entry.name} fill={chartColors[index % chartColors.length]} />)}</Bar></BarChart></ResponsiveContainer></section>
      <section className="pipeline-panel"><header><div><Briefcase size={18} /><span>Proyectos de inversión</span></div><DataState type="pending">Demostrativo</DataState></header>{projects.map((project) => <button key={project.id} onClick={() => setActive("proyectos")}><span><strong>{project.name}</strong><small>{project.stage} · {project.milestone}</small></span><b>{project.progress}%</b><i><em style={{ width: `${project.progress}%` }} /></i></button>)}</section>
    </div>

    <div className="command-status"><Info size={16} weight="fill" /><strong>Modo demostración con base histórica recuperada.</strong><span>Base MIC/DGFI · corte julio 2025. No certificada como vigente en 2026.</span><div><DataState type="official">Base documental</DataState><DataState type="calculated">Calculado</DataState><DataState type="pending">Demostrativo</DataState></div></div>
  </section>;
}

function Filters({ department, setDepartment, character, setCharacter }) { return <div className="filter-row"><Funnel size={18} weight="bold" /><select value={department} onChange={(event) => setDepartment(event.target.value)} aria-label="Departamento">{paraguayDepartments.map((item) => <option key={item}>{item}</option>)}</select><select value={character} onChange={(event) => setCharacter(event.target.value)} aria-label="Carácter">{parkCharacters.map((item) => <option key={item}>{item}</option>)}</select></div>; }

function ParkForm({ value, onSave, onClose }) {
  const [form, setForm] = useState(value ? { ...value, latitude: value.coordinates?.lat ?? "", longitude: value.coordinates?.lon ?? "" } : { name: "", short: "", department: "Central", city: "", character: "Privado", surface: "", resolution: "Pendiente", companies: 0, administrator: "", activity: "", occupied: "No publicado", available: "No publicado", status: "En análisis", sourceState: "Dato demostrativo", latitude: "", longitude: "" });
  const update = (key) => (event) => setForm((current) => ({ ...current, [key]: event.target.value }));
  const submit = (event) => { event.preventDefault(); const { latitude, longitude, position, ...record } = form; onSave({ ...record, id: form.id || safeId("park", form.short || form.name), surface: Number(form.surface), companies: Number(form.companies), coordinates: { lat: Number(latitude), lon: Number(longitude), quality: form.coordinates?.quality || "Ingresada", source: form.coordinates?.source || "Registro local" }, sourceState: form.sourceState || "Dato demostrativo", custom: true }); onClose(); };
  return <form className="form-grid" onSubmit={submit}><label className="span-2">Nombre<input required value={form.name} onChange={update("name")} maxLength={140} /></label><label>Nombre corto<input required value={form.short} onChange={update("short")} maxLength={40} /></label><label>Carácter<select value={form.character} onChange={update("character")}>{parkCharacters.slice(1).map((item) => <option key={item}>{item}</option>)}</select></label><label>Departamento<input required value={form.department} onChange={update("department")} maxLength={60} /></label><label>Distrito<input required value={form.city} onChange={update("city")} maxLength={80} /></label><label>Latitud WGS84<input required min="-90" max="90" step="any" type="number" value={form.latitude} onChange={update("latitude")} /></label><label>Longitud WGS84<input required min="-180" max="180" step="any" type="number" value={form.longitude} onChange={update("longitude")} /></label><label>Superficie (ha)<input required min="0" step="0.0001" type="number" value={form.surface} onChange={update("surface")} /></label><label>Empresas<input min="0" type="number" value={form.companies} onChange={update("companies")} /></label><label>Resolución o estado<input value={form.resolution} onChange={update("resolution")} maxLength={60} /></label><label>Estado<select value={form.status} onChange={update("status")}><option>Habilitado</option><option>En análisis</option><option>Proyecto</option><option>Inactivo</option></select></label><label className="span-2">Administrador<input value={form.administrator} onChange={update("administrator")} maxLength={140} /></label><label className="span-2">Actividad<textarea value={form.activity} onChange={update("activity")} maxLength={240} /></label><div className="form-actions span-2"><button type="button" className="secondary-action" onClick={onClose}>Cancelar</button><button className="primary-action" type="submit">Guardar registro</button></div></form>;
}

function ParkProfile({ park, audit, onClose, openMap }) {
  const display = (value) => value === null || value === undefined || value === "" ? "No publicado" : value;
  const fields = [
    ["Departamento", park.department], ["Distrito", park.city], ["Carácter", park.character], ["Estado", park.status],
    ["Superficie registrada", `${formatNumber(park.surface, { maximumFractionDigits: 4 })} ha`], ["Empresas", park.companies],
    ["Ocupación", park.occupied], ["Disponibilidad", park.available], ["Resolución", park.resolution], ["Administrador", park.administrator],
  ];
  return <Modal title="Ficha integral del parque" onClose={onClose}><article className="park-profile printable-profile"><header><div><DataState type={park.sourceState?.includes("Histórico") ? "official" : "pending"}>{park.sourceState}</DataState><h2>{park.name}</h2><p>{park.short} · {park.city}, {park.department}</p></div><div className={`quality-score ${audit.level.toLowerCase()}`}><strong>{audit.score}%</strong><span>completitud</span></div></header><div className="profile-grid">{fields.map(([label, value]) => <div key={label}><span>{label}</span><strong>{display(value)}</strong></div>)}</div><section className="profile-block"><span>Actividad registrada</span><strong>{display(park.activity)}</strong></section><section className="profile-block"><span>Georreferenciación WGS84</span><strong>{validCoordinates(park) ? `${Number(park.coordinates.lat).toFixed(7)}, ${Number(park.coordinates.lon).toFixed(7)}` : "No publicada"}</strong><small>{park.coordinates?.quality || "Sin validar"} · {park.coordinates?.source || "Fuente no informada"}</small></section><div className="profile-audit"><ShieldCheck size={20} /><div><strong>Control de calidad: {audit.level}</strong><span>{audit.missing.length ? `${audit.missing.length} campo(s) faltante(s): ${audit.missing.join(", ")}` : "Campos de control completos"}. {audit.traceable ? "Registro con fuente declarada." : "Trazabilidad incompleta."}</span></div></div><footer><button className="secondary-action" onClick={() => window.print()}><Printer size={18} /> Imprimir / PDF</button><button className="primary-action compact" onClick={() => openMap(park)}><MapTrifold size={18} /> Ver en mapa</button></footer></article></Modal>;
}

function ImportPreview({ preview, onConfirm, onClose }) {
  return <Modal title="Validación previa de importación" onClose={onClose}><div className="import-preview"><div className="import-summary"><div><strong>{preview.total}</strong><span>filas leídas</span></div><div className="accepted"><strong>{preview.accepted.length}</strong><span>aceptadas</span></div><div className="rejected"><strong>{preview.rejected.length}</strong><span>rechazadas</span></div></div><div className="alert"><Info size={18} /><div><strong>Importación local, no oficial</strong><span>Los registros aceptados quedarán marcados como pendientes de revisión y no se compartirán con otros usuarios.</span></div></div>{preview.rejected.length > 0 && <section className="rejection-list"><h3>Filas rechazadas</h3>{preview.rejected.map((item) => <div key={item.row}><strong>Fila {item.row} · {item.name}</strong><span>{item.errors.join(" · ")}</span></div>)}</section>}<div className="form-actions"><button className="secondary-action" onClick={onClose}>Cancelar</button><button className="primary-action compact" disabled={!preview.accepted.length} onClick={onConfirm}>Importar {preview.accepted.length} registro(s)</button></div></div></Modal>;
}

function ParksView({ parks, filteredParks, filters, selectPark, onSave, onDelete, onImport, publicMode }) {
  const [editing, setEditing] = useState(null); const [profile, setProfile] = useState(null); const [preview, setPreview] = useState(null); const [importError, setImportError] = useState(""); const inputRef = useRef(null);
  const audit = useMemo(() => auditParkData(parks), [parks]);
  const auditById = useMemo(() => Object.fromEntries(audit.records.map((record) => [record.id, record])), [audit]);
  const readImport = async (event) => { const file = event.target.files?.[0]; if (!file) return; setImportError(""); try { if (file.size > 5_000_000) throw new Error("El archivo supera el límite de 5 MB."); const rows = file.name.toLowerCase().endsWith(".xlsx") ? parseXlsxArrayBuffer(await file.arrayBuffer()) : parseCsv(await file.text()); if (!rows.length) throw new Error("No se encontraron filas de datos. Verifique que la primera fila contenga encabezados."); setPreview(validateParkImportRows(rows, parks, file.name)); } catch (error) { setImportError(error.message); } finally { event.target.value = ""; } };
  return <><PageHeading eyebrow="Registro de parques" title="Inventario territorial" actions={<div className="heading-actions"><Filters {...filters} />{!publicMode && <><input ref={inputRef} hidden type="file" accept=".csv,.xlsx,text/csv,application/vnd.openxmlformats-officedocument.spreadsheetml.sheet" onChange={readImport} /><button className="secondary-action" onClick={() => inputRef.current?.click()}><UploadSimple size={18} /> Importar CSV/XLSX</button><button className="primary-action compact" onClick={() => setEditing({})}><Plus size={18} /> Nuevo parque</button></>}</div>} />{importError && <div className="alert error import-alert"><Warning size={18} />{importError}</div>}<section className="table-card"><div className="table-toolbar"><div><h2>{filteredParks.length} de {parks.length} registros</h2><p>Abra una fila para consultar su ficha integral. La calidad se calcula por completitud y trazabilidad.</p></div><DataState type="calculated">Calidad media {audit.summary.average}%</DataState></div><div className="table-scroll"><table><thead><tr><th>Parque</th><th>Ubicación</th><th>Carácter</th><th>Superficie</th><th>Empresas</th><th>Resolución</th><th>Calidad</th>{!publicMode && <th>Acciones</th>}</tr></thead><tbody>{filteredParks.map((park) => { const quality = auditById[park.id]; return <tr key={park.id} onClick={() => setProfile(park)}><td><strong>{park.short}</strong><span>{park.name}</span></td><td>{park.city}<span>{park.department}</span></td><td><span className={`character-badge ${park.character.toLowerCase()}`}>{park.character}</span></td><td>{formatNumber(park.surface, { maximumFractionDigits: 4 })} ha</td><td>{park.companies}</td><td>{park.resolution}</td><td><span className={`quality-pill ${quality?.level.toLowerCase()}`}>{quality?.score}% · {quality?.level}</span></td>{!publicMode && <td><div className="row-actions"><button onClick={(event) => { event.stopPropagation(); setEditing(park); }} aria-label={`Editar ${park.short}`}><PencilSimple size={17} /></button><button onClick={(event) => { event.stopPropagation(); onDelete(park.id); }} aria-label={`Eliminar ${park.short}`}><Trash size={17} /></button></div></td>}</tr>; })}</tbody></table></div></section>{editing && <Modal title={editing.id ? "Editar parque" : "Nuevo parque demostrativo"} onClose={() => setEditing(null)}><ParkForm value={editing.id ? editing : null} onSave={onSave} onClose={() => setEditing(null)} /></Modal>}{profile && <ParkProfile park={profile} audit={auditById[profile.id]} onClose={() => setProfile(null)} openMap={(park) => { setProfile(null); selectPark(park); }} />}{preview && <ImportPreview preview={preview} onClose={() => setPreview(null)} onConfirm={() => { onImport(preview.accepted); setPreview(null); }} />}</>;
}

function ProjectForm({ parks, value, onSave, onClose }) {
  const [form, setForm] = useState(value || { name: "", promoter: "", parkId: parks[0]?.id || "", sector: "", investment: "", stage: "Perfil", progress: 0, milestone: "", due: "" });
  const update = (key) => (event) => setForm((current) => ({ ...current, [key]: event.target.value }));
  const submit = (event) => { event.preventDefault(); onSave({ ...form, id: form.id || safeId("project", form.name), investment: Number(form.investment), progress: Math.max(0, Math.min(100, Number(form.progress))) }); onClose(); };
  return <form className="form-grid" onSubmit={submit}><label className="span-2">Proyecto<input required value={form.name} onChange={update("name")} maxLength={140} /></label><label>Promotor<input required value={form.promoter} onChange={update("promoter")} maxLength={120} /></label><label>Parque<select value={form.parkId} onChange={update("parkId")}>{parks.map((park) => <option value={park.id} key={park.id}>{park.short}</option>)}</select></label><label>Sector<input required value={form.sector} onChange={update("sector")} maxLength={80} /></label><label>Inversión proyectada (USD)<input type="number" min="0" value={form.investment} onChange={update("investment")} /></label><label>Etapa<select value={form.stage} onChange={update("stage")}><option>Idea</option><option>Perfil</option><option>Prefactibilidad</option><option>Evaluación</option><option>Ejecución</option><option>Operación</option></select></label><label>Avance (%)<input type="number" min="0" max="100" value={form.progress} onChange={update("progress")} /></label><label>Próximo hito<input value={form.milestone} onChange={update("milestone")} maxLength={120} /></label><label>Fecha objetivo<input type="date" value={form.due} onChange={update("due")} /></label><div className="form-actions span-2"><button type="button" className="secondary-action" onClick={onClose}>Cancelar</button><button className="primary-action">Guardar proyecto</button></div></form>;
}

function ProjectsView({ projects, parks, onSave, onDelete }) {
  const [editing, setEditing] = useState(null); const total = projects.reduce((sum, item) => sum + Number(item.investment || 0), 0);
  return <><PageHeading eyebrow="Cartera demostrativa" title="Proyectos de inversión" actions={<button className="primary-action compact" onClick={() => setEditing({})}><Plus size={18} /> Nuevo proyecto</button>} /><div className="stats-grid two"><Kpi Icon={Briefcase} value={projects.length} label="proyectos" note="Registros locales ficticios" /><Kpi Icon={CurrencyDollar} value={formatCurrency(total)} label="inversión proyectada" note="Suma demostrativa, no oficial" /></div><section className="cards-grid">{projects.map((project) => { const park = parks.find((item) => item.id === project.parkId); return <article className="project-card" key={project.id}><header><DataState type="pending">Demostrativo</DataState><div className="row-actions"><button onClick={() => setEditing(project)} aria-label="Editar"><PencilSimple size={17} /></button><button onClick={() => onDelete(project.id)} aria-label="Eliminar"><Trash size={17} /></button></div></header><h2>{project.name}</h2><p>{project.promoter}</p><dl><div><dt>Parque</dt><dd>{park?.short || "Sin asignar"}</dd></div><div><dt>Sector</dt><dd>{project.sector}</dd></div><div><dt>Inversión</dt><dd>{formatCurrency(project.investment)}</dd></div><div><dt>Etapa</dt><dd>{project.stage}</dd></div></dl><div className="progress-meta"><span>{project.milestone}</span><strong>{project.progress}%</strong></div><div className="progress-track"><i style={{ width: `${project.progress}%` }} /></div><small>Fecha objetivo: {project.due || "Sin definir"}</small></article>; })}{!projects.length && <EmptyState icon={Briefcase} title="Sin proyectos" text="Agregue el primer proyecto demostrativo." />}</section>{editing && <Modal title={editing.id ? "Editar proyecto" : "Nuevo proyecto demostrativo"} onClose={() => setEditing(null)}><ProjectForm parks={parks} value={editing.id ? editing : null} onSave={onSave} onClose={() => setEditing(null)} /></Modal>}</>;
}

function validCoordinates(park) { return Number.isFinite(Number(park.coordinates?.lat)) && Number.isFinite(Number(park.coordinates?.lon)); }
function markerColor(park) { if (park.character === "Oficial") return "#0f6bb5"; if (park.character === "Mixto") return "#bd7b11"; return "#087f83"; }

function MapViewport({ parks }) {
  const map = useMap();
  useEffect(() => {
    const points = parks.filter(validCoordinates).map((park) => [Number(park.coordinates.lat), Number(park.coordinates.lon)]);
    if (points.length > 1) map.fitBounds(L.latLngBounds(points), { padding: [34, 34], maxZoom: 8 });
    else if (points.length === 1) map.setView(points[0], 12);
  }, [map, parks]);
  return null;
}

function MapCanvas({ parks, selected, setSelected, geoJson }) {
  const mappedParks = parks.filter(validCoordinates); const omitted = parks.length - mappedParks.length;
  return <div className="map-canvas" aria-label="Mapa georreferenciado de parques industriales"><MapContainer center={[-23.45, -58.35]} zoom={5} minZoom={4} maxZoom={18} scrollWheelZoom className="leaflet-map"><TileLayer attribution="Tiles &copy; Esri" maxZoom={19} url="https://server.arcgisonline.com/ArcGIS/rest/services/World_Topo_Map/MapServer/tile/{z}/{y}/{x}" /><MapViewport parks={mappedParks} />{geoJson && <GeoJSON data={geoJson} style={{ color: "#ae2b71", weight: 2, fillColor: "#ae2b71", fillOpacity: .24 }} pointToLayer={(_, latlng) => L.circleMarker(latlng, { radius: 6, color: "#ae2b71", fillOpacity: .65 })} />}{mappedParks.map((park) => { const active = selected?.id === park.id; const color = markerColor(park); const point = [Number(park.coordinates.lat), Number(park.coordinates.lon)]; return <CircleMarker key={park.id} center={point} radius={active ? 10 : 7} pathOptions={{ color: "#ffffff", weight: active ? 3 : 2, fillColor: active ? "#ae2b71" : color, fillOpacity: .95 }} eventHandlers={{ click: (event) => { setSelected(park); event.target._map.flyTo(point, Math.max(event.target._map.getZoom(), 12)); } }}><Tooltip direction="top" offset={[0, -7]}>{park.short}</Tooltip><Popup><strong>{park.name}</strong><br />{park.city}, {park.department}<br /><small>{park.coordinates.quality} · {park.coordinates.lat.toFixed(6)}, {park.coordinates.lon.toFixed(6)}</small></Popup></CircleMarker>; })}</MapContainer>{omitted > 0 && <div className="map-warning">{omitted} registro(s) sin coordenadas WGS84 no se muestran.</div>}<div className="map-scale">WGS84 · ubicación puntual · Esri</div></div>;
}

function GisView({ parks, selected, setSelected, geoState, setGeoState }) {
  const inputRef = useRef(null);
  const importFile = async (event) => { const file = event.target.files?.[0]; if (!file) return; try { if (file.size > 5_000_000) throw new Error("El archivo supera el límite de 5 MB."); const parsed = parseGeoJson(await file.text()); setGeoState({ ...parsed, name: file.name, error: "" }); } catch (error) { setGeoState({ data: null, name: file.name, error: error.message, featureCount: 0, geometryTypes: [] }); } finally { event.target.value = ""; } };
  const sample = JSON.stringify({ type: "FeatureCollection", features: [{ type: "Feature", properties: { name: "Polígono demostrativo" }, geometry: { type: "Polygon", coordinates: [[[-57.7, -25.2], [-57.4, -25.2], [-57.4, -25.5], [-57.7, -25.5], [-57.7, -25.2]]] } }] }, null, 2);
  return <><PageHeading eyebrow="Georreferenciación" title="Mapa GIS y capas" actions={<div className="heading-actions"><input ref={inputRef} type="file" accept=".geojson,.json,application/geo+json,application/json" hidden onChange={importFile} /><button className="secondary-action" onClick={() => downloadText("sigpi-ejemplo.geojson", sample, "application/geo+json")}><DownloadSimple size={18} /> Ejemplo</button><button className="primary-action compact" onClick={() => inputRef.current?.click()}><UploadSimple size={18} /> Importar GeoJSON</button></div>} /><div className="gis-grid"><section className="map-card"><MapCanvas parks={parks} selected={selected} setSelected={setSelected} geoJson={geoState.data} /></section><aside className="detail-panel"><div className="detail-heading"><div><DataState type={selected?.sourceState?.includes("Histórico") ? "official" : "pending"}>{selected?.sourceState || "Sin selección"}</DataState><h2>{selected?.short || "Parque"}</h2><p>{selected?.city}, {selected?.department}</p></div><div className="resolution"><span>Resolución/estado</span><strong>{selected?.resolution}</strong></div></div><div className="fact-grid"><div><span>Superficie</span><strong>{formatNumber(selected?.surface)} ha</strong></div><div><span>Empresas</span><strong>{selected?.companies}</strong></div><div><span>Carácter</span><strong>{selected?.character}</strong></div><div><span>Estado</span><strong>{selected?.status}</strong></div></div><div className="quality-card"><div className="panel-title"><MapTrifold size={18} /> Coordenada del registro</div><div className="quality-row"><span>Latitud / longitud</span><strong>{validCoordinates(selected) ? `${Number(selected.coordinates.lat).toFixed(6)}, ${Number(selected.coordinates.lon).toFixed(6)}` : "No disponible"}</strong></div><div className="quality-row"><span>Calidad</span><strong>{selected?.coordinates?.quality || "Sin validar"}</strong></div><div className="quality-row"><span>Fuente</span><strong>{selected?.coordinates?.source || "No informada"}</strong></div></div><div className="quality-card layer-registry"><div className="panel-title"><Stack size={18} /> Registro de capas y precisión</div><div className="layer-record"><i className="active" /><div><strong>Mapa base Esri World Topographic</strong><span>Referencia visual externa · escala variable</span></div><DataState type="calculated">Base</DataState></div><div className="layer-record"><i className="active" /><div><strong>Puntos de parques DGFI</strong><span>WGS84 · ubicación puntual documental; no es polígono predial</span></div><DataState type="official">Documental</DataState></div><div className="layer-record"><i className={geoState.data ? "active imported" : ""} /><div><strong>GeoJSON del usuario</strong><span>{geoState.data ? `${geoState.name} · ${geoState.featureCount} entidades` : "Sin capa cargada"}</span></div><DataState type={geoState.data ? "pending" : "calculated"}>{geoState.data ? "Sin validar" : "Inactiva"}</DataState></div></div><div className="quality-card"><div className="panel-title"><MapTrifold size={18} /> Capa importada</div>{geoState.error && <div className="alert error"><Warning size={18} />{geoState.error}</div>}{geoState.data ? <><div className="quality-row"><span>Archivo</span><strong>{geoState.name}</strong></div><div className="quality-row"><span>Entidades</span><strong>{geoState.featureCount}</strong></div><div className="quality-row"><span>Geometrías</span><strong>{geoState.geometryTypes.join(", ") || "Sin geometría"}</strong></div><p className="fine-print">La capa se interpreta como WGS84 (EPSG:4326). Valide el CRS y la geometría antes de uso técnico.</p></> : <EmptyState icon={UploadSimple} title="Sin capa GeoJSON" text="Importe puntos, líneas o polígonos en WGS84 para superponerlos al mapa." />}</div></aside></div></>;
}

function DocumentForm({ parks, onSave, onClose }) {
  const [form, setForm] = useState({ parkId: parks[0]?.id || "", name: "", category: "Institucional", status: "Pendiente", version: 1, updated: new Date().toISOString().slice(0, 10) });
  const update = (key) => (event) => setForm((current) => ({ ...current, [key]: event.target.value }));
  const submit = (event) => { event.preventDefault(); onSave({ ...form, id: safeId("doc", form.name), version: Number(form.version) }); onClose(); };
  return <form className="form-grid" onSubmit={submit}><label className="span-2">Nombre del documento<input required value={form.name} onChange={update("name")} maxLength={160} /></label><label>Parque<select value={form.parkId} onChange={update("parkId")}>{parks.map((park) => <option value={park.id} key={park.id}>{park.short}</option>)}</select></label><label>Categoría<select value={form.category} onChange={update("category")}><option>Institucional</option><option>Jurídico</option><option>Cartografía</option><option>Ambiental</option><option>Infraestructura</option><option>Evaluación</option></select></label><label>Estado<select value={form.status} onChange={update("status")}><option>Pendiente</option><option>En revisión</option><option>Revisado</option><option>Observado</option></select></label><label>Versión<input type="number" min="1" value={form.version} onChange={update("version")} /></label><div className="alert span-2"><Info size={18} />Esta versión registra metadatos; no carga ni publica archivos privados.</div><div className="form-actions span-2"><button type="button" className="secondary-action" onClick={onClose}>Cancelar</button><button className="primary-action">Registrar metadato</button></div></form>;
}

function DocumentsView({ documents, parks, onSave, onDelete }) {
  const [open, setOpen] = useState(false);
  return <><PageHeading eyebrow="Gestión documental" title="Control de expedientes" actions={<button className="primary-action compact" onClick={() => setOpen(true)}><Plus size={18} /> Registrar documento</button>} /><section className="table-card"><div className="table-toolbar"><div><h2>{documents.length} metadatos registrados</h2><p>No se almacenan archivos binarios ni documentos privados en esta versión estática.</p></div><DataState type="pending">Almacenamiento local</DataState></div><div className="table-scroll"><table><thead><tr><th>Documento</th><th>Parque</th><th>Categoría</th><th>Estado</th><th>Versión</th><th>Actualización</th><th>Acción</th></tr></thead><tbody>{documents.map((doc) => <tr key={doc.id}><td><strong>{doc.name}</strong></td><td>{parks.find((park) => park.id === doc.parkId)?.short || "Sin asignar"}</td><td>{doc.category}</td><td><DataState type={doc.status === "Revisado" ? "official" : "pending"}>{doc.status}</DataState></td><td>v{doc.version}</td><td>{doc.updated}</td><td><div className="row-actions"><button onClick={() => onDelete(doc.id)} aria-label="Eliminar"><Trash size={17} /></button></div></td></tr>)}</tbody></table></div></section>{open && <Modal title="Registrar metadato documental" onClose={() => setOpen(false)}><DocumentForm parks={parks} onSave={onSave} onClose={() => setOpen(false)} /></Modal>}</>;
}

function EvaluationView({ parks, selected, setSelected, evaluations, setEvaluations }) {
  const current = evaluations[selected.id] || {}; const summary = summarizeEvaluations(current);
  const update = (criterionId, value) => setEvaluations((all) => ({ ...all, [selected.id]: { ...(all[selected.id] || {}), [criterionId]: value } }));
  return <><PageHeading eyebrow="Matriz técnica demostrativa" title="Evaluación multicriterio" actions={<select className="standalone-select" value={selected.id} onChange={(event) => setSelected(parks.find((park) => park.id === event.target.value))}>{parks.map((park) => <option value={park.id} key={park.id}>{park.short}</option>)}</select>} /><div className="evaluation-grid"><section className="evaluation-card"><div className="evaluation-summary"><div><span>Criterios con estado “Cumple”</span><strong>{summary.complete} de {summary.total}</strong><DataState type="calculated">{summary.score}% calculado</DataState></div><div className="progress-track"><i style={{ width: `${summary.score}%` }} /></div><p>La matriz es demostrativa. No equivale a dictamen, permiso ni certificación.</p></div><div className="checklist">{evaluationCriteria.map((criterion, index) => <div className="check-row" key={criterion.id}><span className="check-index">{String(index + 1).padStart(2, "0")}</span><div><strong>{criterion.label}</strong><span>{criterion.group}</span></div><select value={current[criterion.id] || "Sin evidencia"} onChange={(event) => update(criterion.id, event.target.value)}><option>Cumple</option><option>Parcial</option><option>Pendiente</option><option>No cumple</option><option>Sin evidencia</option></select></div>)}</div></section><aside className="evidence-panel"><div className="panel-title"><ShieldCheck size={19} /> Trazabilidad</div><div className="evidence-item"><CheckCircle size={20} weight="fill" /><div><strong>{selected.name}</strong><span>Registro: {selected.resolution}</span></div></div><div className="evidence-item"><Database size={20} weight="fill" /><div><strong>Persistencia local</strong><span>Los cambios se guardan en localStorage de este navegador.</span></div></div><div className="evidence-warning"><Warning size={20} weight="fill" /><div><strong>Sin validación administrativa</strong><span>Los estados no prueban cumplimiento legal ni técnico.</span></div></div><div className="criteria-notes"><h3>Próxima integración operativa</h3><ul><li>evidencias documentales versionadas;</li><li>parámetros normativos con fuente;</li><li>aprobación por rol;</li><li>registro de cambios en servidor.</li></ul></div></aside></div></>;
}

const auditFieldLabels = { name: "nombre", short: "nombre corto", department: "departamento", city: "distrito", character: "carácter", surface: "superficie", resolution: "resolución", administrator: "administrador", activity: "actividad", status: "estado", coordinates: "coordenadas", companies: "empresas", occupied: "ocupación", available: "disponibilidad", sourceState: "estado de fuente" };

function DataQualityView({ parks, setSelected, setActive }) {
  const audit = useMemo(() => auditParkData(parks), [parks]);
  const exportAudit = () => downloadText("sigpi-calidad-datos.csv", toCsv(audit.records.map((record) => ({ ...record, missingText: record.missing.map((field) => auditFieldLabels[field] || field).join("; "), staleText: record.stale.map((field) => auditFieldLabels[field] || field).join("; ") })), [["Parque", "short"], ["Completitud %", "score"], ["Nivel", "level"], ["Campos faltantes", "missingText"], ["Datos a revisar", "staleText"], ["Coordenadas válidas", "coordinatesValid"], ["Trazabilidad", "traceable"], ["Duplicado", "duplicate"]]), "text/csv;charset=utf-8");
  return <><PageHeading eyebrow="Gobierno de información" title="Calidad y trazabilidad de datos" actions={<button className="secondary-action" onClick={exportAudit}><DownloadSimple size={18} /> Exportar auditoría</button>} /><section className="quality-hero"><div><DataState type="calculated">Métrica calculada</DataState><h2>{audit.summary.average}% de completitud media</h2><p>Control automático sobre 13 campos, validez de coordenadas, fuente declarada, duplicados y señales de desactualización. No certifica vigencia administrativa.</p></div><div className="quality-ring" style={{ "--score": `${audit.summary.average * 3.6}deg` }}><strong>{audit.summary.average}</strong><span>/100</span></div></section><div className="quality-kpis"><article><CheckCircle size={23} /><strong>{audit.summary.high}</strong><span>calidad alta</span></article><article><Info size={23} /><strong>{audit.summary.medium}</strong><span>calidad media</span></article><article><Warning size={23} /><strong>{audit.summary.low}</strong><span>calidad baja</span></article><article><Crosshair size={23} /><strong>{audit.summary.invalidCoordinates}</strong><span>coordenadas inválidas</span></article><article><ArrowClockwise size={23} /><strong>{audit.summary.stale}</strong><span>registros a actualizar</span></article></div><section className="table-card"><div className="table-toolbar"><div><h2>Auditoría por registro</h2><p>Alta: ≥85% y trazable · Media: ≥65% · Baja: &lt;65%. Los valores “No publicado” se consideran faltantes.</p></div><DataState type={audit.summary.duplicates ? "pending" : "official"}>{audit.summary.duplicates} duplicado(s)</DataState></div><div className="table-scroll"><table><thead><tr><th>Parque</th><th>Completitud</th><th>Campos faltantes</th><th>Actualización</th><th>Coordenadas</th><th>Trazabilidad</th></tr></thead><tbody>{audit.records.map((record) => <tr key={record.id} onClick={() => { const park = parks.find((item) => item.id === record.id); setSelected(park); setActive("parques"); }}><td><strong>{record.short}</strong>{record.duplicate && <span>Posible duplicado</span>}</td><td><span className={`quality-pill ${record.level.toLowerCase()}`}>{record.score}% · {record.level}</span></td><td>{record.missing.length ? record.missing.map((field) => auditFieldLabels[field] || field).join(", ") : "Completo"}</td><td>{record.stale.length ? <DataState type="pending">Revisar</DataState> : <DataState type="official">Sin alerta</DataState>}</td><td>{record.coordinatesValid ? <DataState type="official">Válidas</DataState> : <DataState type="pending">Inválidas</DataState>}</td><td>{record.traceable ? "Fuente declarada" : "Incompleta"}</td></tr>)}</tbody></table></div></section><section className="method-card"><ShieldCheck size={24} /><div><strong>Regla verificable</strong><span>Completitud = campos informados ÷ 13 × 100. La categoría Alta exige además fuente general y fuente de coordenadas. No se imputan valores faltantes.</span></div></section></>;
}

function ReportsView({ parks, projects, documents, evaluations }) {
  const exportParks = () => downloadText("sigpi-parques.csv", toCsv(parks, [["Parque", "name"], ["Departamento", "department"], ["Distrito", "city"], ["Carácter", "character"], ["Superficie ha", "surface"], ["Empresas", "companies"], ["Resolución", "resolution"], ["Calidad", "sourceState"]]), "text/csv;charset=utf-8");
  const exportProjects = () => downloadText("sigpi-proyectos-demo.csv", toCsv(projects, [["Proyecto", "name"], ["Promotor", "promoter"], ["Sector", "sector"], ["Inversión USD", "investment"], ["Etapa", "stage"], ["Avance %", "progress"], ["Hito", "milestone"], ["Fecha", "due"]]), "text/csv;charset=utf-8");
  const reportRows = parks.map((park) => ({ ...park, score: summarizeEvaluations(evaluations[park.id]).score }));
  return <><PageHeading eyebrow="Salidas y exportación" title="Reportes" actions={<button className="primary-action compact" onClick={() => window.print()}><FileText size={18} /> Imprimir / Guardar PDF</button>} /><div className="report-grid"><article className="report-card"><Factory size={28} weight="duotone" /><h2>Inventario de parques</h2><p>Exporta la base visible con ubicación, superficie, resolución y calidad del dato.</p><button className="secondary-action" onClick={exportParks}><DownloadSimple size={18} /> Descargar CSV</button></article><article className="report-card"><Briefcase size={28} weight="duotone" /><h2>Cartera de proyectos</h2><p>Exporta los registros demostrativos de inversión y seguimiento.</p><button className="secondary-action" onClick={exportProjects}><DownloadSimple size={18} /> Descargar CSV</button></article><article className="report-card"><FileText size={28} weight="duotone" /><h2>Reporte ejecutivo</h2><p>Usa la impresión del navegador para generar un PDF de esta vista.</p><button className="secondary-action" onClick={() => window.print()}><FileText size={18} /> Abrir impresión</button></article></div><section className="table-card printable"><div className="table-toolbar"><div><h2>Resumen ejecutivo SIGPI</h2><p>Base histórica {sourceCut}; proyectos y matrices demostrativos.</p></div><DataState type="calculated">Generado en navegador</DataState></div><div className="table-scroll"><table><thead><tr><th>Parque</th><th>Territorio</th><th>Superficie</th><th>Empresas</th><th>Evaluación demo</th></tr></thead><tbody>{reportRows.map((park) => <tr key={park.id}><td><strong>{park.short}</strong></td><td>{park.city}, {park.department}</td><td>{formatNumber(park.surface)} ha</td><td>{park.companies}</td><td>{park.score}%</td></tr>)}</tbody></table></div><footer className="report-foot">Documentos registrados: {documents.length} · Proyectos demo: {projects.length} · Generado: {new Date().toLocaleDateString("es-PY")}</footer></section></>;
}

function AdminView({ state, restoreDefaults, importBackup }) {
  const backupRef = useRef(null);
  const exportBackup = () => downloadText("sigpi-respaldo-local.json", JSON.stringify({ schema: 1, exportedAt: new Date().toISOString(), ...state }, null, 2), "application/json");
  const readBackup = async (event) => { const file = event.target.files?.[0]; if (!file) return; try { const data = JSON.parse(await file.text()); if (data.schema !== 1 || !Array.isArray(data.parks) || !Array.isArray(data.projects)) throw new Error("Respaldo incompatible"); importBackup(data); } catch (error) { window.alert(`No se pudo importar: ${error.message}`); } finally { event.target.value = ""; } };
  return <><PageHeading eyebrow="Configuración local" title="Administración" actions={<DataState type="pending">No apto para datos privados</DataState>} /><div className="admin-grid"><section className="panel"><div className="panel-title"><LockKey size={19} /> Seguridad y alcance</div><div className="alert"><Warning size={20} /><div><strong>Frontend estático sin autenticación real</strong><span>La vista interna es una demostración. GitHub Pages no debe recibir expedientes, secretos ni datos personales.</span></div></div><ul className="plain-list"><li>Validación básica de formularios y límites de archivos.</li><li>Sin ejecución de HTML importado.</li><li>Sin backend, permisos efectivos ni persistencia multiusuario.</li><li>Backend objetivo: API REST + PostgreSQL/PostGIS + OIDC.</li></ul></section><section className="panel"><div className="panel-title"><UsersThree size={19} /> Roles preparados</div><div className="role-row"><strong>Consulta pública</strong><span>Dashboard, inventario, GIS y reportes.</span></div><div className="role-row"><strong>Técnico</strong><span>Registro, documentos, evaluación y seguimiento.</span></div><div className="role-row"><strong>Administrador</strong><span>Catálogos, usuarios, permisos y auditoría.</span></div><p className="fine-print">Los roles son arquitectura prevista; no controlan acceso en esta versión.</p></section><section className="panel"><div className="panel-title"><Database size={19} /> Datos locales</div><div className="summary-strip"><div><strong>{state.parks.length}</strong><span>parques</span></div><div><strong>{state.projects.length}</strong><span>proyectos</span></div><div><strong>{state.documents.length}</strong><span>documentos</span></div></div><div className="button-stack"><button className="secondary-action" onClick={exportBackup}><DownloadSimple size={18} /> Exportar respaldo JSON</button><input ref={backupRef} hidden type="file" accept="application/json,.json" onChange={readBackup} /><button className="secondary-action" onClick={() => backupRef.current?.click()}><UploadSimple size={18} /> Importar respaldo</button><button className="danger-action" onClick={restoreDefaults}><ArrowClockwise size={18} /> Restaurar demostración</button></div></section><section className="panel"><div className="panel-title"><ListChecks size={19} /> Catálogos</div>{["Estado de parque", "Etapa de proyecto", "Categoría documental", "Estado de evaluación", "Departamento y distrito"].map((item) => <div className="quality-row" key={item}><span>{item}</span><DataState type="pending">Backend pendiente</DataState></div>)}</section></div></>;
}

function migrateParkCoordinates(records) {
  const verifiedById = new Map(historicalParks.map((park) => [park.id, park.coordinates]));
  return records.map((park) => ({ ...park, coordinates: verifiedById.get(park.id) || park.coordinates }));
}

export function App() {
  const [parks, setParks] = useState(() => migrateParkCoordinates(loadLocal("sigpi.parks", historicalParks)));
  const [projects, setProjects] = useState(() => loadLocal("sigpi.projects", demoProjects));
  const [documents, setDocuments] = useState(() => loadLocal("sigpi.documents", demoDocuments));
  const [evaluations, setEvaluations] = useState(() => loadLocal("sigpi.evaluations", initialEvaluations));
  const [active, setActive] = useState("dashboard"); const [selected, setSelected] = useState(() => parks[0]);
  const [department, setDepartment] = useState("Todos"); const [character, setCharacter] = useState("Todos"); const [search, setSearch] = useState("");
  const [publicMode, setPublicMode] = useState(true); const [geoState, setGeoState] = useState({ data: null, name: "", error: "", featureCount: 0, geometryTypes: [] });
  useEffect(() => { saveLocal("sigpi.parks", parks); }, [parks]); useEffect(() => { saveLocal("sigpi.projects", projects); }, [projects]); useEffect(() => { saveLocal("sigpi.documents", documents); }, [documents]); useEffect(() => { saveLocal("sigpi.evaluations", evaluations); }, [evaluations]);
  useEffect(() => { if (publicMode && !navItems.find(([id]) => id === active)?.[3]) setActive("dashboard"); }, [publicMode, active]);
  useEffect(() => { if (!parks.some((park) => park.id === selected?.id)) setSelected(parks[0]); }, [parks, selected]);
  const filteredParks = useMemo(() => { const term = search.trim().toLowerCase(); return parks.filter((park) => (department === "Todos" || park.department === department) && (character === "Todos" || park.character === character) && (!term || [park.name, park.short, park.city, park.department, park.resolution].some((value) => String(value).toLowerCase().includes(term)))); }, [parks, department, character, search]);
  const savePark = (park) => setParks((items) => items.some((item) => item.id === park.id) ? items.map((item) => item.id === park.id ? park : item) : [...items, park]);
  const importParks = (records) => setParks((items) => [...items, ...records]);
  const saveProject = (project) => setProjects((items) => items.some((item) => item.id === project.id) ? items.map((item) => item.id === project.id ? project : item) : [...items, project]);
  const removePark = (id) => { if (window.confirm("El registro se eliminará de este navegador. Puede recuperarse desde Administración.")) setParks((items) => items.filter((item) => item.id !== id)); };
  const removeProject = (id) => { if (window.confirm("Eliminar el proyecto demostrativo de este navegador?")) setProjects((items) => items.filter((item) => item.id !== id)); };
  const removeDocument = (id) => { if (window.confirm("Eliminar este metadato documental?")) setDocuments((items) => items.filter((item) => item.id !== id)); };
  const restoreDefaults = () => { if (!window.confirm("Restaurar todos los datos de demostración y descartar cambios locales?")) return; setParks(historicalParks); setProjects(demoProjects); setDocuments(demoDocuments); setEvaluations(initialEvaluations); setSelected(historicalParks[0]); };
  const importBackup = (data) => { const importedParks = migrateParkCoordinates(data.parks); setParks(importedParks); setProjects(data.projects); setDocuments(Array.isArray(data.documents) ? data.documents : []); setEvaluations(data.evaluations || {}); setSelected(importedParks[0]); };
  const filters = { department, setDepartment, character, setCharacter };
  const sourceMessage = publicMode ? "Vista pública: módulos sin edición. La base histórica no está certificada como vigente en 2026." : "Gestión interna demostrativa: los cambios permanecen en localStorage y no se comparten.";
  return <div className={`app-shell ${active === "dashboard" ? "dashboard-shell" : ""}`}><Sidebar active={active} setActive={setActive} publicMode={publicMode} /><div className="workspace"><Header search={search} setSearch={setSearch} publicMode={publicMode} setPublicMode={setPublicMode} /><SourceBand message={sourceMessage} /><main className={`main-content ${active === "dashboard" ? "dashboard-content" : ""}`}>{active === "dashboard" && <Dashboard parks={parks} projects={projects} setActive={setActive} selected={selected} setSelected={setSelected} />}{active === "parques" && <ParksView parks={parks} filteredParks={filteredParks} filters={filters} selectPark={(park) => { setSelected(park); setActive("gis"); }} onSave={savePark} onDelete={removePark} onImport={importParks} publicMode={publicMode} />}{active === "proyectos" && <ProjectsView projects={projects} parks={parks} onSave={saveProject} onDelete={removeProject} />}{active === "gis" && <GisView parks={filteredParks} selected={selected || filteredParks[0]} setSelected={setSelected} geoState={geoState} setGeoState={setGeoState} />}{active === "calidad" && <DataQualityView parks={parks} setSelected={setSelected} setActive={setActive} />}{active === "documentos" && <DocumentsView documents={documents} parks={parks} onSave={(doc) => setDocuments((items) => [...items, doc])} onDelete={removeDocument} />}{active === "evaluacion" && selected && <EvaluationView parks={parks} selected={selected} setSelected={setSelected} evaluations={evaluations} setEvaluations={setEvaluations} />}{active === "reportes" && <ReportsView parks={filteredParks} projects={projects} documents={documents} evaluations={evaluations} />}{active === "admin" && <AdminView state={{ parks, projects, documents, evaluations }} restoreDefaults={restoreDefaults} importBackup={importBackup} />}</main></div></div>;
}
